    /** Translate [english] into the active language, falling back to English. */
    fun t(english: String): String {
        val l = AppLanguage.current()
        if (l == "en") return english
        val row = table[english] ?: return english
        return when (l) {
            "fa" -> row.first.ifBlank { english }
            "zh" -> row.second.ifBlank { english }
            else -> english
        }
    }

    /** Translate a %s template, then substitute [args] in order. */
    fun tf(english: String, vararg args: Any?): String {
        var out = t(english)
        for (a in args) {
            val i = out.indexOf("%s")
            if (i == -1) break
            out = out.substring(0, i) + a.toString() + out.substring(i + 2)
        }
        return out
    }
